"use client";
import { useState } from "react";
import { User } from "@/lib/types";
import { Loader2, Trash2, Edit, Save, X } from "lucide-react";
import { findAllUsers } from "@/lib/dbActions";
const UserAdmin = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingUser, setEditingUser] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<User>>({});
  async function setAllUsers() {
    setUsers(await findAllUsers());
  }
  setAllUsers();

  const handleEdit = (user: User) => {
    setEditingUser(user.id);
    setEditForm(user);
  };

  return (
    <div className="p-6">
      <div className="pt-6 p-4 text-neutral-200 text-xl mb-6">
        User Management
      </div>

      <div className="bg-gray-800 rounded-lg overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left text-gray-300">
            <thead className="text-xs text-gray-300 uppercase bg-gray-700">
              <tr>
                <th className="px-6 py-3">Name</th>
                <th className="px-6 py-3">Email</th>
                <th className="px-6 py-3">Roles</th>
                <th className="px-6 py-3">Joined</th>
                <th className="px-6 py-3">Actions</th>
              </tr>
            </thead>
            <tbody>
              {users.map((user) => (
                <tr
                  key={user.id}
                  className="bg-gray-800 border-b border-gray-700 hover:bg-gray-750"
                >
                  <td className="px-6 py-4">
                    {editingUser === user.id ? (
                      <input
                        type="text"
                        value={editForm.name || ""}
                        onChange={(e) =>
                          setEditForm({ ...editForm, name: e.target.value })
                        }
                        className="bg-gray-700 text-white p-2 rounded w-full"
                      />
                    ) : (
                      <div className="flex items-center">
                        <div className="w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center mr-3">
                          {user.name.charAt(0).toUpperCase()}
                        </div>
                        {user.name}
                      </div>
                    )}
                  </td>
                  <td className="px-6 py-4">
                    {editingUser === user.id ? (
                      <input
                        type="email"
                        value={editForm.email || ""}
                        onChange={(e) =>
                          setEditForm({ ...editForm, email: e.target.value })
                        }
                        className="bg-gray-700 text-white p-2 rounded w-full"
                      />
                    ) : (
                      user.email
                    )}
                  </td>
                  <td className="px-6 py-4">
                    {editingUser === user.id ? (
                      <div className="flex flex-wrap gap-2">
                        {["member", "admin", "moderator"].map((role) => (
                          <button
                            key={role}
                            onClick={() => toggleRole(role)}
                            className={`px-2 py-1 rounded text-xs ${
                              editForm.roles?.includes(role)
                                ? "bg-blue-500 text-white"
                                : "bg-gray-600 text-gray-300"
                            }`}
                          >
                            {role}
                          </button>
                        ))}
                      </div>
                    ) : (
                      <div className="flex flex-wrap gap-1">
                        {user.roles.map((role) => (
                          <span
                            key={role}
                            className="px-2 py-1 bg-blue-500 text-white rounded text-xs"
                          >
                            {role}
                          </span>
                        ))}
                      </div>
                    )}
                  </td>
                  <td className="px-6 py-4">
                    {new Date(user.created_at).toLocaleDateString()}
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex space-x-2">
                      {editingUser === user.id ? (
                        <>
                          <button
                            onClick={() => handleSave(user.id)}
                            className="text-green-400 hover:text-green-300"
                          >
                            <Save className="h-4 w-4" />
                          </button>
                          <button
                            onClick={() => {
                              setEditingUser(null);
                              setEditForm({});
                            }}
                            className="text-gray-400 hover:text-gray-300"
                          >
                            <X className="h-4 w-4" />
                          </button>
                        </>
                      ) : (
                        <>
                          <button
                            onClick={() => handleEdit(user)}
                            className="text-blue-400 hover:text-blue-300"
                          >
                            <Edit className="h-4 w-4" />
                          </button>
                          <button
                            onClick={() => handleDelete(user.id)}
                            className="text-red-400 hover:text-red-300"
                          >
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default UserAdmin;
